SELECT SUM(t.v) / COUNT(*) AS v FROM (SELECT CASE WHEN o.currency = 'BDT' THEN o.total_bdt ELSE o.total_amount * x.bdt_per_unit END AS v FROM orders o LEFT JOIN currency_rates x ON x.rate_date = CAST(o.order_at AS DATE) AND x.currency = o.currency WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-06-01 00:00:00' AND o.order_at < TIMESTAMP '2025-07-01 00:00:00') t
